const manual = $('Manual Trigger');
if (!manual.isExecuted) return [];
const trigger = manual.first().json || {};
const request = trigger.body || trigger;
if (!request.request_id) return [];
const summary = $('Expand TLS Results').isExecuted
  ? ($('Expand TLS Results').all().map(item => item.json).find(item => item.kind === 'summary') || {})
  : {};
const meta = summary.meta || {};
const resultStatus = summary.status === 'error' ? 'failed' : summary.status === 'partial' ? 'partial' : 'success';
const findings = Number(meta.findings || 0);
return [{ json: {
  request_id: request.request_id,
  workflow_code: 'wf-03',
  status: resultStatus,
  summary: 'Escaneo TLS completado: ' + findings + ' hallazgo(s) procesado(s).',
  details: meta
} }];

const response = $input.first()?.json?.body || $input.first()?.json || {};
const findings = Array.isArray(response.findings) ? response.findings : [];
const summary = response.summary || {
  kind: 'summary',
  job_type: 'tls_expiry',
  interval_min: 1440,
  status: 'error',
  meta: { total: 0, checked: 0, failed: 1, blocked: 0, findings: 0 }
};
return [
  ...findings.map(finding => ({ json: { kind: 'finding', ...finding } })),
  { json: { ...summary, kind: 'summary' } }
];
